def _tab(d, s, r0, xs, cols):
    """Fill a table: xs go down column A from row r0; cols maps a column letter to a formula template with {r}."""
    for i, x in enumerate(xs):
        r = r0 + i; d[f'A{r}'] = x
        for c, f in cols.items(): s[f'{c}{r}'] = f.format(r=r)
    return [f'{c}{r0 + i}' for c in cols for i in range(len(xs))]


_col = lambda c, r0, n: [f'{c}{r0 + i}' for i in range(n)]

