def _rv(n, num, q, tools, line, c):
    return ST(n, f'<div class="rv-n">מפגש {num}</div><div class="rv-q">{TX(q)}</div><ul>' + ''.join(f'<li>{TX(t)}</li>' for t in tools) + f'</ul><div class="rv-l">{TX(line)}</div>', cls='rv ' + c)


